1	import {
2	  ProposedActionSchema,
3	  RecommendationSchema,
4	  type BearCase,
5	  type Evidence,
6	  type FundamentalReport,
7	  type Instrument,
8	  type Mandate,
9	  type MarketContextReport,
10	  type PortfolioSnapshot,
11	  type ProposedAction,
12	  type Recommendation,
13	  type RiskReport,
14	} from "@sonar-ai/core";
15	import { z } from "zod";
16	import { ClaimDraftSchema, type Agent } from "./types";
17	
18	/**
19	 * Portfolio Manager — owns capital allocation. It proposes target weights from
20	 * the committee's research and revises them after risk + critique.
21	 *
22	 * Runs TWICE through one definition: a PROPOSAL pass (no risk report / bear
23	 * case in context) and a REVISION pass (both present). It reasons over
24	 * structured summaries — never raw evidence packs — and it does NOT compute
25	 * risk math or override the Risk Officer.
26	 */
27	
28	/** What the Portfolio Manager is allowed to see. Populated by the orchestrator. */
29	export interface PortfolioManagerContext {
30	  portfolio: PortfolioSnapshot;
31	  mandate: Mandate;
32	  /** The investable candidate universe. */
33	  instruments: Instrument[];
34	  /** Research summaries (not raw evidence). */
35	  fundamentalReports: FundamentalReport[];
36	  marketContext: MarketContextReport | null;
37	  /** The evidence records the PM may cite in its bull/context/bear claims. */
38	  evidence: Evidence[];
39	  /** Revision-only: the Risk Officer's verdict. Present ⇒ this is the revision pass. */
40	  riskReport?: RiskReport | null;
41	  /** Revision-only: the Bear/Critic's case. */
42	  bearCase?: BearCase | null;
43	}
44	
45	// The model supplies each action's instrument, side, target weight, and
46	// evidence — not its ID or notional. `finalize` computes the notional from NAV
47	// (so it always satisfies the risk engine's amount≈weight×NAV check) and
48	// assigns the ID.
49	const ProposedActionDraftSchema = ProposedActionSchema.omit({
50	  id: true,
51	  amount: true,
52	});
53	
54	export const RecommendationDraftSchema = RecommendationSchema.omit({
55	  id: true,
56	  revision: true,
57	  actions: true,
58	  bull: true,
59	  context: true,
60	  bear: true,
61	  expectedCashAfter: true,
62	}).extend({
63	  actions: z.array(ProposedActionDraftSchema),
64	  bull: z.array(ClaimDraftSchema),
65	  context: z.array(ClaimDraftSchema),
66	  bear: z.array(ClaimDraftSchema),
67	});
68	export type RecommendationDraft = z.infer<typeof RecommendationDraftSchema>;
69	
70	function isRevision(ctx: PortfolioManagerContext): boolean {
71	  return Boolean(ctx.riskReport || ctx.bearCase);
72	}
73	
74	const round2 = (n: number): number => Math.round(n * 100) / 100;
75	
76	// ── First-draft prompt (Axel owns the final wording) ─────────────────────────
77	
78	const INSTRUCTIONS = `You are the Portfolio Manager on an investment committee. You own capital allocation.
79	
80	From the research summaries, propose a set of paper allocation actions. For each:
81	- name the instrument, the side (buy/sell), and a target weight as a fraction of NAV;
82	- cite the evidence that supports it.
83	
84	Stay within the mandate: no single position over its limit, no sector over its
85	limit, and hold at least the minimum cash. Then give the structured case:
86	- bull: why this allocation can work;
87	- context: the external backdrop it depends on;
88	- bear: what you are knowingly accepting.
89	Give an overall confidence (0-1) and the conditions that would invalidate the plan.
90	
91	Every claim MUST cite evidenceIds from the provided list. Do NOT compute risk
92	metrics or ratios yourself — the Risk Officer does that. Do NOT set position IDs
93	or notional amounts — provide target weights only.
94	
95	On a REVISION pass you also receive the Risk Officer's report and the Bear/Critic's
96	case: adopt any resized sizing, address the strongest bear points, and keep the
97	plan within the mandate. Return only the required JSON.`;
98	
99	function summarizeFundamentals(reports: FundamentalReport[]): string {
100	  if (reports.length === 0) return "(no fundamental reports)";
101	  return reports
102	    .map(
103	      (r) =>
104	        `- ${r.instrumentId}: quality — ${r.quality} | valuation — ${r.valuation}` +
105	        (r.claims.length
106	          ? ` | evidence: ${r.claims.flatMap((c) => c.evidenceIds).join(", ")}`
107	          : ""),
108	    )
109	    .join("\n");
110	}
111	
112	function summarizeRisk(risk: RiskReport): string {
113	  const checks = risk.checks
114	    .map(
115	      (c) =>
116	        `  · ${c.actionId}: ${c.result}` +
117	        (c.breachCode ? ` (${c.breachCode})` : "") +
118	        ` — ${c.detail}`,
119	    )
120	    .join("\n");
121	  return [
122	    `Hard blocks: ${risk.hardBlocks.length ? risk.hardBlocks.join(", ") : "none"}`,
123	    `Checks:\n${checks}`,
124	  ].join("\n");
125	}
126	
127	function buildInput(ctx: PortfolioManagerContext): string {
128	  const nav = ctx.portfolio.nav.amount;
129	  const { limits } = ctx.mandate;
130	
131	  const universe =
132	    ctx.instruments
133	      .map((i) => `- ${i.symbol} (${i.id}) — sector ${i.sector}`)
134	      .join("\n") || "(none)";
135	
136	  const evidenceList =
137	    ctx.evidence.map((e) => `- ${e.id} | ${e.title}`).join("\n") || "(none)";
138	
139	  const blocks = [
140	    `Pass: ${isRevision(ctx) ? "REVISION" : "PROPOSAL"}.`,
141	    `Portfolio: NAV ${nav} ${ctx.portfolio.baseCurrency}, cash ${ctx.portfolio.cash.amount}, ${ctx.portfolio.positions.length} positions.`,
142	    `Mandate limits: position ≤ ${limits.maxGrossExposurePerPosition}, sector ≤ ${limits.maxSectorExposure}, cash ≥ ${limits.minCashRatio}, turnover ≤ ${limits.maxTurnoverPerEvent}.`,
143	    `Candidate universe:\n${universe}`,
144	    `Fundamental research:\n${summarizeFundamentals(ctx.fundamentalReports)}`,
145	    `Market context:\n${ctx.marketContext ? ctx.marketContext.summary : "(none)"}`,
146	    `Evidence you may cite:\n${evidenceList}`,
147	  ];
148	
149	  if (ctx.riskReport) blocks.push(`Risk Officer report:\n${summarizeRisk(ctx.riskReport)}`);
150	  if (ctx.bearCase) {
151	    blocks.push(
152	      `Bear/Critic case:\n- weaknesses: ${ctx.bearCase.weaknesses.join("; ") || "none"}\n- failure scenarios: ${ctx.bearCase.failureScenarios.join("; ") || "none"}`,
153	    );
154	  }
155	
156	  blocks.push(
157	    `Produce the recommendation as JSON matching the required schema. Provide target weights only; every claim.evidenceIds entry MUST come from the evidence list above.`,
158	  );
159	  return blocks.join("\n\n");
160	}
161	
162	/** Assign IDs, compute notionals from NAV, and derive expected cash. */
163	function finalize(
164	  draft: RecommendationDraft,
165	  ctx: PortfolioManagerContext,
166	): Recommendation {
167	  const revision = isRevision(ctx) ? 1 : 0;
168	  const id = revision === 1 ? "rec_final" : "rec_proposal";
169	  const nav = ctx.portfolio.nav.amount;
170	  const currency = ctx.portfolio.baseCurrency;
171	
172	  const actions: ProposedAction[] = draft.actions.map((a) => ({
173	    id: `acn_${a.instrumentId}_r${revision}`,
174	    instrumentId: a.instrumentId,
175	    side: a.side,
176	    targetWeight: a.targetWeight,
177	    amount: { amount: round2(a.targetWeight * nav), currency },
178	    evidenceIds: a.evidenceIds,
179	  }));
180	
181	  const buys = actions
182	    .filter((a) => a.side === "buy")
183	    .reduce((sum, a) => sum + a.amount.amount, 0);
184	  const sells = actions
185	    .filter((a) => a.side === "sell")
186	    .reduce((sum, a) => sum + a.amount.amount, 0);
187	  const expectedCashAfter = {
188	    amount: round2(ctx.portfolio.cash.amount - buys + sells),
189	    currency,
190	  };
191	
192	  const withIds = (
193	    claims: RecommendationDraft["bull"],
194	    kind: "bull" | "context" | "bear",
195	  ) => claims.map((c, i) => ({ id: `clm_${id}_${kind}_${i}`, ...c }));
196	
197	  return {
198	    id,
199	    revision,
200	    actions,
201	    bull: withIds(draft.bull, "bull"),
202	    context: withIds(draft.context, "context"),
203	    bear: withIds(draft.bear, "bear"),
204	    confidence: draft.confidence,
205	    invalidationConditions: draft.invalidationConditions,
206	    expectedCashAfter,
207	  };
208	}
209	
210	export const portfolioManager: Agent<
211	  PortfolioManagerContext,
212	  RecommendationDraft,
213	  Recommendation
214	> = {
215	  def: {
216	    stage: "portfolio_manager",
217	    instructions: INSTRUCTIONS,
218	    outputSchema: RecommendationDraftSchema,
219	    buildInput,
220	  },
221	  finalize,
222	};
