1	import {
2	  CommitteeReportSchema,
3	  type CommitteeReport,
4	  type Evidence,
5	  type MaterialEvent,
6	  type PaperOrder,
7	  type PortfolioComparison,
8	  type Recommendation,
9	  type UserDecision,
10	} from "@sonar-ai/core";
11	import { z } from "zod";
12	import type { Agent } from "./types";
13	
14	/**
15	 * Communications / Report Writer — turns the finished decision into a plain
16	 * narrative and a one-line summary.
17	 *
18	 * It runs ONLY after the human decision (enforced structurally: its context
19	 * requires a non-null `userDecision`) and it CANNOT influence allocation — its
20	 * output has no action or weight fields. Compliance disclaimers are injected by
21	 * `finalize`, never left to the model.
22	 */
23	
24	/** What the Report Writer is allowed to see. Populated by the orchestrator. */
25	export interface ReportWriterContext {
26	  /** The final recommendation the human ruled on. */
27	  recommendation: Recommendation;
28	  /** The human's decision. Required — this agent never runs before it exists. */
29	  userDecision: UserDecision;
30	  /** The paper orders that actually applied (empty if rejected). */
31	  appliedOrders: PaperOrder[];
32	  /** The current-vs-proposed comparison. */
33	  comparison: PortfolioComparison;
34	  /** The originating event, for narrative color. */
35	  event?: MaterialEvent | null;
36	  /** Evidence records the narrative may reference. */
37	  evidence: Evidence[];
38	}
39	
40	export const CommitteeReportDraftSchema = CommitteeReportSchema.omit({
41	  id: true,
42	});
43	export type CommitteeReportDraft = z.infer<typeof CommitteeReportDraftSchema>;
44	
45	/** Always present, regardless of what the model writes. */
46	const REQUIRED_DISCLAIMERS = ["Paper trading only.", "Not investment advice."];
47	
48	// ── First-draft prompt (Axel owns the final wording) ─────────────────────────
49	
50	const INSTRUCTIONS = `You are the Communications / Report Writer on an investment committee. The decision is already made.
51	
52	Write, in plain language:
53	- narrative: what the committee examined, what it found, and what was decided;
54	- decisionSummary: one sentence stating the outcome.
55	
56	Describe only what happened. Do NOT recommend new trades, change any allocation,
57	or second-guess the decision — your role is to explain, not to decide. You may
58	add scenario-specific caveats to disclaimers, but standard compliance notices are
59	added automatically. Return only the required JSON.`;
60	
61	function buildInput(ctx: ReportWriterContext): string {
62	  const outcome = ctx.userDecision.decision.toUpperCase();
63	  const actions =
64	    ctx.recommendation.actions
65	      .map((a) => `- ${a.side} ${a.instrumentId} to ${Math.round(a.targetWeight * 100)}% of NAV`)
66	      .join("\n") || "(no actions)";
67	  const applied =
68	    ctx.appliedOrders
69	      .map((o) => `- ${o.side} ${o.quantity} ${o.instrumentId} @ ${o.price.amount} (${o.notional.amount} ${o.notional.currency})`)
70	      .join("\n") || "(none applied)";
71	
72	  return [
73	    `Human decision: ${outcome}${ctx.userDecision.note ? ` — "${ctx.userDecision.note}"` : ""}.`,
74	    ctx.event ? `Originating event: ${ctx.event.headline} — ${ctx.event.summary}` : `No specific event.`,
75	    `Recommended allocation:\n${actions}`,
76	    `Applied paper orders:\n${applied}`,
77	    `Cash after: ${ctx.comparison.proposedCash.amount} ${ctx.comparison.proposedCash.currency} of ${ctx.comparison.currentNav.amount} NAV.`,
78	    `Write the report as JSON matching the required schema.`,
79	  ].join("\n\n");
80	}
81	
82	/** Assign the ID and force the mandatory compliance disclaimers. */
83	function finalize(draft: CommitteeReportDraft): CommitteeReport {
84	  const extra = draft.disclaimers.filter((d) => !REQUIRED_DISCLAIMERS.includes(d));
85	  return {
86	    id: "rpt_main",
87	    narrative: draft.narrative,
88	    decisionSummary: draft.decisionSummary,
89	    disclaimers: [...REQUIRED_DISCLAIMERS, ...extra],
90	  };
91	}
92	
93	export const reportWriter: Agent<
94	  ReportWriterContext,
95	  CommitteeReportDraft,
96	  CommitteeReport
97	> = {
98	  def: {
99	    stage: "report_writer",
100	    instructions: INSTRUCTIONS,
101	    outputSchema: CommitteeReportDraftSchema,
102	    buildInput,
103	  },
104	  finalize: (draft) => finalize(draft),
105	};
